let currentGrade = localStorage.getItem('questAcademyGrade') || '7';

function getActiveData() {
  return currentGrade === '5' ? GRADE5_DATA : COURSE_DATA;
}

function getStateKey() {
  return currentGrade === '5' ? 'grade5QuestState' : 'questAcademyState';
}

function getTotalQuests() {
  return getActiveData().reduce((n, m) => n + m.quests.length, 0);
}

let STATE = JSON.parse(localStorage.getItem(getStateKey()) || '{"xp":0,"done":{},"last":"","streak":0,"quizScores":{},"quizBonuses":{},"quizAttempts":{}}');
if (!STATE.quizAttempts) STATE.quizAttempts = {};
let LAST_NARRATION = '';

// --- Server persistence ---
function getProfileId() {
  return currentGrade === '5' ? 'seydina' : 'cheikh';
}

let syncTimer = null;
let MUTATION = 0; // bumped on every local change; guards against stale server responses

function pushStateToServer(replace) {
  clearTimeout(syncTimer);
  const profileId = getProfileId();
  const snapshot = JSON.stringify({ state: STATE, replace: !!replace });
  syncTimer = setTimeout(() => {
    fetch('/api/state/' + profileId, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: snapshot
    }).then(r => setSyncStatus(r.ok)).catch(() => setSyncStatus(false));
  }, replace ? 0 : 600);
}

function logEvent(eventType, detail, xpDelta) {
  fetch('/api/event/' + getProfileId(), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ eventType, detail, xpDelta })
  }).catch(() => {});
}

function setSyncStatus(ok) {
  const el = document.getElementById('syncStatus');
  if (!el) return;
  el.textContent = ok ? '☁️ Saved' : '⚠️ Offline — saved on this device';
  el.className = 'syncStatus ' + (ok ? 'ok' : 'off');
}

function isEmptyState(s) {
  return !s || ((s.xp || 0) === 0 && Object.keys(s.done || {}).length === 0 && Object.keys(s.quizScores || {}).length === 0);
}

async function loadStateFromServer() {
  const profileId = getProfileId();
  const mutationAtRequest = MUTATION;
  try {
    const res = await fetch('/api/state/' + profileId);
    if (!res.ok) throw new Error('bad response');
    const data = await res.json();
    // Discard stale responses: grade switched or local changes happened while fetching
    if (getProfileId() !== profileId || MUTATION !== mutationAtRequest) return;
    if (isEmptyState(data.state) && !isEmptyState(STATE)) {
      // One-time import of existing local progress
      pushStateToServer();
    } else if (!isEmptyState(data.state)) {
      STATE = data.state;
      localStorage.setItem(getStateKey(), JSON.stringify(STATE));
      buildCourse(getActiveData());
    }
    setSyncStatus(true);
  } catch (e) {
    setSyncStatus(false);
  }
}

function save() {
  MUTATION++;
  localStorage.setItem(getStateKey(), JSON.stringify(STATE));
  pushStateToServer();
  updateStats();
  renderProgressTracker();
}

function showProgressSheet() {
  const sheet = document.getElementById('progressTracker');
  if (!sheet) return;
  sheet.classList.remove('hidden');
  sheet.setAttribute('aria-hidden', 'false');
  document.body.classList.add('sheetOpen');
  const close = sheet.querySelector('.closeSheet');
  if (close) close.focus();
}

function hideProgressSheet() {
  const sheet = document.getElementById('progressTracker');
  if (!sheet) return;
  sheet.classList.add('hidden');
  sheet.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('sheetOpen');
}

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') hideProgressSheet();
});

function onGradeSelectChange(select) {
  switchGrade(select.value);
}

function updateStats() {
  document.getElementById('xp').textContent = STATE.xp;
  document.getElementById('done').textContent = Object.keys(STATE.done).length;
  document.getElementById('streak').textContent = STATE.streak || 0;
  let total = getTotalQuests();
  let prefix = currentGrade === '5' ? '5th' : '7th';
  let b = 'Starter';
  if (STATE.xp >= 150) b = 'Quest Knight';
  if (STATE.xp >= 300) b = 'Focus Wizard';
  if (STATE.xp >= 500) b = prefix + ' Grade Ready';
  document.getElementById('badge').textContent = b;
  const pct = Math.round((Object.keys(STATE.done).length / Math.max(total, 1)) * 100);
  const bar = document.getElementById('globalProgressBar');
  if (bar) bar.style.width = pct + '%';
  const label = document.getElementById('globalProgressLabel');
  if (label) label.textContent = pct + '% complete';
}

function moduleStats(moduleId) {
  const mod = getActiveData().find(m => m.id === moduleId);
  let done = mod.quests.filter((_, i) => STATE.done[`${moduleId}-${i}`]).length;
  return { done, total: mod.quests.length, pct: Math.round(done / mod.quests.length * 100) };
}

function renderProgressTracker() {
  const box = document.getElementById('progressTracker');
  if (!box) return;
  let html = '<div class="sheetHeader"><div><p class="sheetEyebrow">YAABA ACADEMY</p><h2>Progress Report</h2></div><button class="secondary closeSheet" type="button" aria-label="Close progress report" onclick="hideProgressSheet()">Close</button></div><p>Check completion bars, quiz scores, XP, and export a progress report.</p><div class="progressBar"><span id="globalProgressBar"></span></div><strong id="globalProgressLabel"></strong><div class="progressGrid">';
  getActiveData().forEach(m => {
    let s = moduleStats(m.id);
    html += `<div class="progressCard"><h3>${m.emoji} ${m.name}</h3><div class="miniBar"><span style="width:${s.pct}%"></span></div><p>${s.done}/${s.total} quests complete | ${s.pct}%</p><div class="questDots">${m.quests.map((q, i) => `<span title="${q.title}" class="dot ${STATE.done[`${m.id}-${i}`] ? 'on' : ''}"></span>`).join('')}</div></div>`;
  });
  html += '</div><div class="exportBox"><button onclick="downloadProgress()">Download Progress Report</button><button class="secondary" onclick="resetProgressConfirm()">Reset Progress</button></div>';
  box.innerHTML = html;
  box.setAttribute('aria-hidden', box.classList.contains('hidden') ? 'true' : 'false');
  updateStats();
}

function downloadProgress() {
  let gradeLabel = currentGrade === '5' ? '5th Grade' : 'Rising 7th Grade';
  let lines = [
    gradeLabel + ' Yaaba Academy - Progress Report',
    'Generated: ' + new Date().toLocaleString(),
    'XP: ' + STATE.xp,
    'Quests Done: ' + Object.keys(STATE.done).length + '/' + getTotalQuests(),
    'Streak: ' + (STATE.streak || 0),
    ''
  ];
  getActiveData().forEach(m => {
    let s = moduleStats(m.id);
    lines.push(m.name + ': ' + s.done + '/' + s.total + ' complete');
    m.quests.forEach((q, i) => {
      let id = `${m.id}-${i}`;
      let score = STATE.quizScores[id] !== undefined ? ' | Quiz: ' + STATE.quizScores[id] + '%' : '';
      lines.push('  - ' + (STATE.done[id] ? '[DONE] ' : '[ ] ') + q.title + score);
    });
    lines.push('');
  });
  let blob = new Blob([lines.join('\n')], { type: 'text/plain' });
  let a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = (currentGrade === '5' ? 'grade5' : 'grade7') + '_quest_progress_report.txt';
  a.click();
  URL.revokeObjectURL(a.href);
}

function resetProgressConfirm() {
  if (confirm('Reset all progress, XP, streak, and quiz scores?')) {
    STATE = { xp: 0, done: {}, last: '', streak: 0, quizScores: {}, quizBonuses: {}, quizAttempts: {} };
    MUTATION++;
    localStorage.setItem(getStateKey(), JSON.stringify(STATE));
    pushStateToServer(true); // full replace on explicit reset
    updateStats();
    renderProgressTracker();
    buildCourse(getActiveData());
  }
}

function markDone(id, card) {
  if (!STATE.done[id]) {
    STATE.done[id] = true;
    STATE.xp += 25;
    let today = new Date().toDateString();
    if (STATE.last !== today) {
      let yesterday = new Date(Date.now() - 86400000).toDateString();
      if (STATE.last === yesterday) {
        STATE.streak = (STATE.streak || 0) + 1;
      } else {
        STATE.streak = 1;
      }
      STATE.last = today;
    }
    save();
    logEvent('quest_done', { questId: id }, 25);
    burstConfetti(card);
  }
  card.classList.add('done');
}

let remaining = 20 * 60;
let interval = null;

function renderTimer() {
  let m = String(Math.floor(remaining / 60)).padStart(2, '0');
  let s = String(remaining % 60).padStart(2, '0');
  document.getElementById('timer').textContent = `${m}:${s}`;
}

function startTimer() {
  if (interval) return;
  interval = setInterval(() => {
    remaining--;
    renderTimer();
    if (remaining <= 0) {
      clearInterval(interval);
      interval = null;
      alert('Sprint complete. Take a 3-minute movement break!');
    }
  }, 1000);
}

function resetTimer() {
  clearInterval(interval);
  interval = null;
  remaining = 20 * 60;
  renderTimer();
}

// Cached British-voice pick. Note: true Cockney voices do NOT exist in browser
// speechSynthesis engines — the nearest available is standard UK English, so we
// prioritise the best-quality en-GB voices (Google UK, then Daniel/Arthur).
let CHOSEN_VOICE = null;
let VOICE_PICKED = false;

function pickVoice() {
  if (!('speechSynthesis' in window)) return null;
  const voices = window.speechSynthesis.getVoices();
  if (!voices || !voices.length) return null;
  CHOSEN_VOICE =
    voices.find(v => /Google UK English Male/i.test(v.name)) ||
    voices.find(v => /Google UK English Female/i.test(v.name)) ||
    voices.find(v => /(Daniel|Arthur)/i.test(v.name) && /en-GB/i.test(v.lang || '')) ||
    voices.find(v => /^en-GB/i.test(v.lang || '')) ||
    voices.find(v => /English|US|Natural|Jenny|Aria/i.test(v.name)) ||
    null;
  VOICE_PICKED = true;
  return CHOSEN_VOICE;
}

function speak(text) {
  LAST_NARRATION = text;
  if (!('speechSynthesis' in window)) {
    alert('Narration is not supported in this browser. Try Microsoft Edge, Chrome, or Safari.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.rate = .92;
  u.pitch = 1.05;
  u.volume = 1;
  u.lang = 'en-GB';
  if (!VOICE_PICKED || !CHOSEN_VOICE) pickVoice();
  if (CHOSEN_VOICE) u.voice = CHOSEN_VOICE;
  window.speechSynthesis.speak(u);
}

function stopNarration() {
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
}

function replayLastNarration() {
  if (LAST_NARRATION) speak(LAST_NARRATION);
}

function selectChoice(btn) {
  let group = btn.parentElement;
  [...group.querySelectorAll('button')].forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
}

function shuffleArray(arr) {
  let a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const QUIZ_MAX_ATTEMPTS = 3;

// A quiz is finished when it has 3 recorded attempts OR any attempt hit 100%.
function quizIsExhausted(id) {
  const arr = (STATE.quizAttempts && STATE.quizAttempts[id]) || [];
  return arr.length >= QUIZ_MAX_ATTEMPTS || arr.some(p => p >= 100);
}

function quizItemsHtml(id, q) {
  let items = q.interactiveQuiz || [];
  return items.map((item, i) => {
    if (item.type === 'multiple_choice') {
      return `<div class="quizItem" data-type="multiple_choice" data-answer="${item.answer}"><p>${i + 1}. ${item.question}</p><div class="choiceGroup">${shuffleArray(item.choices).map(c => `<button class="choice" onclick="selectChoice(this)" data-value="${c}">${c}</button>`).join('')}</div></div>`;
    }
    if (item.type === 'true_false') {
      return `<div class="quizItem" data-type="true_false" data-answer="${item.answer}"><p>${i + 1}. ${item.question}</p><div class="choiceGroup"><button class="choice" onclick="selectChoice(this)" data-value="true">True</button><button class="choice" onclick="selectChoice(this)" data-value="false">False</button></div></div>`;
    }
    if (item.type === 'drag_match') {
      let shuffledClues = shuffleArray(item.pairs.map(p => p[1]));
      return `<div class="quizItem matchItem" data-type="drag_match" data-pairs='${JSON.stringify(item.pairs)}'><p>${i + 1}. ${item.question}</p><div class="matchGrid">${item.pairs.map(p => `<label>${p[0]}<select><option value="">Choose clue</option>${shuffledClues.map(x => `<option value="${x}">${x}</option>`).join('')}</select></label>`).join('')}</div></div>`;
    }
    return '';
  }).join('');
}

function renderInteractiveQuiz(id, q) {
  // Locked/completed state on load: quiz exhausted -> show composite, no retry.
  if (quizIsExhausted(id)) {
    const attempts = (STATE.quizAttempts[id] || []);
    const composite = STATE.quizScores[id] !== undefined
      ? STATE.quizScores[id]
      : Math.round(attempts.reduce((a, b) => a + b, 0) / Math.max(attempts.length, 1));
    return `<div class="quiz interactiveQuiz quizLocked" data-quiz-id="${id}"><strong>Interactive Quiz</strong><div class="feedback" id="${id}-interactive-fb" style="color:#22c55e">Final score: ${composite}% (composite of ${attempts.length} attempt${attempts.length === 1 ? '' : 's'})</div></div>`;
  }
  return `<div class="quiz interactiveQuiz" data-quiz-id="${id}">${quizInnerHtml(id, q)}</div>`;
}

// Inner content (items + grade button + feedback) — reused for retries.
function quizInnerHtml(id, q) {
  const attemptNo = ((STATE.quizAttempts[id] || []).length) + 1;
  return `<strong>Interactive Quiz</strong><div class="quizAttemptTag">Attempt ${attemptNo} of ${QUIZ_MAX_ATTEMPTS}</div>${quizItemsHtml(id, q)}<button class="secondary" onclick="gradeInteractiveQuiz('${id}', this.closest('.interactiveQuiz'))">Grade Quiz</button><div class="feedback" id="${id}-interactive-fb"></div>`;
}

// Look up the quest data object from a composite quest id like "math-2".
function questById(id) {
  const dash = id.lastIndexOf('-');
  const modId = id.slice(0, dash);
  const idx = parseInt(id.slice(dash + 1), 10);
  const mod = getActiveData().find(m => m.id === modId);
  return mod ? mod.quests[idx] : null;
}

function retryInteractiveQuiz(id) {
  const q = questById(id);
  const box = document.querySelector('.interactiveQuiz[data-quiz-id="' + id + '"]');
  if (!q || !box) return;
  box.classList.remove('quizLocked');
  box.innerHTML = quizInnerHtml(id, q); // fresh shuffle
}

function gradeInteractiveQuiz(id, box) {
  if (box.classList.contains('quizLocked')) return; // already graded/locked
  let items = [...box.querySelectorAll('.quizItem')];
  let correct = 0, total = items.length;
  items.forEach(item => {
    let type = item.dataset.type;
    if (type === 'multiple_choice' || type === 'true_false') {
      let selected = item.querySelector('.selected');
      let ok = selected && selected.dataset.value.toLowerCase() === item.dataset.answer.toLowerCase();
      if (ok) correct++;
      // Lock choices and show correct/wrong classes
      item.querySelectorAll('.choice').forEach(b => {
        b.disabled = true;
        if (b.dataset.value.toLowerCase() === item.dataset.answer.toLowerCase()) b.classList.add('correct');
        else if (b.classList.contains('selected')) b.classList.add('wrong');
      });
    } else if (type === 'drag_match') {
      let pairs = JSON.parse(item.dataset.pairs);
      let selects = [...item.querySelectorAll('select')];
      if (selects.every((sel, i) => sel.value === pairs[i][1])) correct++;
      selects.forEach((sel, i) => {
        sel.disabled = true;
        sel.classList.add(sel.value === pairs[i][1] ? 'correct' : 'wrong');
      });
    }
  });
  let pct = Math.round(correct / Math.max(total, 1) * 100);

  // Record this attempt (max QUIZ_MAX_ATTEMPTS)
  if (!STATE.quizAttempts[id]) STATE.quizAttempts[id] = [];
  if (STATE.quizAttempts[id].length < QUIZ_MAX_ATTEMPTS) STATE.quizAttempts[id].push(pct);
  const attempts = STATE.quizAttempts[id];
  const attemptNo = attempts.length;

  // Lock the attempt UI: disable the grade button, mark box locked
  box.classList.add('quizLocked');
  const gradeBtn = box.querySelector('button.secondary');
  if (gradeBtn) gradeBtn.disabled = true;

  logEvent('quiz_attempt', { quiz: id, attempt: attemptNo, score: pct }, 0);

  let fb = document.getElementById(id + '-interactive-fb');
  const finished = attempts.length >= QUIZ_MAX_ATTEMPTS || attempts.some(p => p >= 100);

  if (!finished) {
    // More attempts allowed
    if (fb) {
      fb.textContent = `Score: ${correct}/${total} (${pct}%). `;
      fb.style.color = pct >= 80 ? '#22c55e' : '#f59e0b';
    }
    const retryBtn = document.createElement('button');
    retryBtn.className = 'secondary retryQuizBtn';
    retryBtn.textContent = `Retry (attempt ${attemptNo + 1} of ${QUIZ_MAX_ATTEMPTS})`;
    retryBtn.onclick = () => retryInteractiveQuiz(id);
    if (fb) fb.after(retryBtn);
    save();
    return;
  }

  // Final attempt -> composite score
  const composite = Math.round(attempts.reduce((a, b) => a + b, 0) / attempts.length);
  STATE.quizScores[id] = composite;
  let bonus = 0;
  if (composite >= 80 && !STATE.quizBonuses[id]) {
    STATE.quizBonuses[id] = true;
    STATE.xp += 15;
    bonus = 15;
  }
  save();
  logEvent('quiz_graded', { questId: id, score: composite }, bonus);
  if (fb) {
    fb.textContent = `Final score: ${composite}% (composite of ${attempts.length} attempts). ${composite >= 80 ? (STATE.quizBonuses[id] ? 'Bonus XP awarded.' : 'Bonus XP already earned.') : 'Great effort — review the mission and try the next quest.'}`;
    fb.style.color = composite >= 80 ? '#22c55e' : '#f59e0b';
  }
  if (composite >= 80) speak('Excellent quiz work. You scored at least eighty percent and earned bonus XP.');
}

function burstConfetti(target) {
  let rect = target.getBoundingClientRect();
  let cx = rect.left + rect.width / 2;
  let cy = rect.top + rect.height / 2;
  let colors = ['#38bdf8', '#fef08a', '#22c55e', '#fb923c', '#818cf8', '#f472b6'];
  for (let i = 0; i < 30; i++) {
    let p = document.createElement('div');
    p.className = 'confetti';
    p.style.left = cx + 'px';
    p.style.top = cy + 'px';
    p.style.background = colors[i % colors.length];
    p.style.setProperty('--dx', (Math.random() * 300 - 150) + 'px');
    p.style.setProperty('--dy', (Math.random() * -200 - 50) + 'px');
    document.body.appendChild(p);
    setTimeout(() => p.remove(), 1200);
  }
}

function courseSubjectKey() {
  return 'qaSubject' + currentGrade;
}

function getSelectedSubject(modules) {
  let sel = localStorage.getItem(courseSubjectKey());
  const valid = ['__all__', ...modules.map(m => m.id)];
  if (!sel || !valid.includes(sel)) {
    // Default to first subject on mobile-width, "All" on desktop.
    sel = (window.innerWidth <= 650 && modules.length) ? modules[0].id : '__all__';
  }
  return sel;
}

function selectSubject(id) {
  localStorage.setItem(courseSubjectKey(), id);
  applySubjectFilter(id);
  renderSubjectTabs();
  const course = document.getElementById('course');
  if (course) course.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function applySubjectFilter(id) {
  const course = document.getElementById('course');
  if (!course) return;
  course.querySelectorAll('.module').forEach(sec => {
    const mid = sec.getAttribute('data-module-id');
    sec.style.display = (id === '__all__' || id === mid) ? '' : 'none';
  });
}

function renderSubjectTabs() {
  const bar = document.getElementById('subjectTabs');
  if (!bar) return;
  const modules = getActiveData();
  const sel = getSelectedSubject(modules);
  let html = `<button class="subjectTab${sel === '__all__' ? ' active' : ''}" onclick="selectSubject('__all__')">🗂️ All</button>`;
  modules.forEach(m => {
    html += `<button class="subjectTab${sel === m.id ? ' active' : ''}" onclick="selectSubject('${m.id}')">${m.emoji} ${m.name}</button>`;
  });
  bar.innerHTML = html;
}

function buildCourse(modules) {
  let course = document.getElementById('course');
  course.innerHTML = '';
  modules.forEach(m => {
    let wrap = document.createElement('section');
    wrap.className = 'module';
    wrap.setAttribute('data-module-id', m.id);
    wrap.style.setProperty('--mcolor', m.color);
    let artHtml = m.image
      ? `<img class="moduleArt" src="${m.image}" alt="Anime-style visual for ${m.name}" />`
      : `<div class="moduleArtEmoji"><div>${m.emoji}</div><div>⭐</div><div>🎯</div><div>🧩</div><div>🏆</div></div>`;
    wrap.innerHTML = `<div class="moduleHead"><div><h2>${m.emoji} ${m.name}</h2><p>${m.narrationIntro}</p><button class="secondary" onclick='speak(${JSON.stringify(m.narrationIntro)})'>Narrate Module</button></div><span>${m.quests.length} quests</span></div>${artHtml}<div class="questGrid"></div>`;
    let grid = wrap.querySelector('.questGrid');
    m.quests.forEach((q, idx) => {
      let id = `${m.id}-${idx}`;
      let narr = q.narration || `Mission briefing. ${q.title}. ${q.mission} Your artifact is: ${q.task} First, open the explore link if needed. Then work for one focused sprint. When finished, explain your answer out loud and mark the quest done.`;
      let card = document.createElement('article');
      card.className = 'quest' + (STATE.done[id] ? ' done' : '');
      let score = STATE.quizScores[id] !== undefined ? `<span class="chip">Quiz: ${STATE.quizScores[id]}%</span>` : '';
      card.innerHTML = `<h3>${q.title}</h3><div class="chips"><span class="chip">${q.minutes} min</span><span class="chip">+25 XP</span><span class="chip">Audio Ready</span>${score}</div><p class="mission">${q.mission}</p><p class="task"><strong>Mission artifact:</strong> ${q.task}</p><details class="transcript"><summary>Narration transcript</summary><p>${narr}</p></details><div class="questActions"><button onclick='speak(${JSON.stringify(narr)})'>Play Narration</button><a class="link" target="_blank" href="${q.video}">Watch / Explore</a><button onclick="markDone('${id}',this.closest('.quest'))">Mark Done</button></div>${renderInteractiveQuiz(id, q)}`;
      grid.appendChild(card);
    });
    course.appendChild(wrap);
  });
  renderSubjectTabs();
  applySubjectFilter(getSelectedSubject(modules));
  renderProgressTracker();
  if (typeof renderWeekly === 'function') renderWeekly();
}

function switchGrade(grade) {
  if (grade === currentGrade) return;
  currentGrade = grade;
  localStorage.setItem('questAcademyGrade', grade);
  STATE = JSON.parse(localStorage.getItem(getStateKey()) || '{"xp":0,"done":{},"last":"","streak":0,"quizScores":{},"quizBonuses":{},"quizAttempts":{}}');
  if (!STATE.quizAttempts) STATE.quizAttempts = {};
  document.getElementById('hero7').classList.toggle('hidden', grade !== '7');
  document.getElementById('hero5').classList.toggle('hidden', grade !== '5');
  document.getElementById('sources7').classList.toggle('hidden', grade !== '7');
  document.getElementById('sources5').classList.toggle('hidden', grade !== '5');
  document.getElementById('grade5Btn').classList.toggle('active', grade === '5');
  document.getElementById('grade7Btn').classList.toggle('active', grade === '7');
  const gradeSelect = document.getElementById('gradeSelect');
  if (gradeSelect) gradeSelect.value = grade;
  resetTimer();
  updateStats();
  renderTimer();
  buildCourse(getActiveData());
  loadStateFromServer();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

if ('speechSynthesis' in window) {
  window.speechSynthesis.onvoiceschanged = () => { pickVoice(); };
  pickVoice();
}

document.getElementById('grade5Btn').classList.toggle('active', currentGrade === '5');
document.getElementById('grade7Btn').classList.toggle('active', currentGrade === '7');
const initialGradeSelect = document.getElementById('gradeSelect');
if (initialGradeSelect) initialGradeSelect.value = currentGrade;
if (currentGrade === '5') {
  document.getElementById('hero7').classList.add('hidden');
  document.getElementById('hero5').classList.remove('hidden');
  document.getElementById('sources7').classList.add('hidden');
  document.getElementById('sources5').classList.remove('hidden');
}
updateStats();
renderTimer();
buildCourse(getActiveData());
loadStateFromServer();
